// sortable by build time so the newest few versions can be kept for pages still running older code
const CORE_CACHE = 'crystal-core-' + "20261012232414448" + '-' + VERSION;
const SPRITE_CACHE = 'crystal-sprites';
const BASE = new URL(self.registration.scope).pathname;
const spriteKey = (p) => BASE + p + '?v=' + SPRITES[p];

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CORE_CACHE).then((c) => c.addAll(CORE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    (async () => {
      const cores = (await caches.keys()).filter((k) => k.startsWith('crystal-core-')).sort();
      for (const k of cores.slice(0, -3)) await caches.delete(k);
      // drop sprite files that were removed or changed
      const sc = await caches.open(SPRITE_CACHE);
      const wanted = new Set(Object.keys(SPRITES).map((p) => new URL(spriteKey(p), self.location.origin).href));
      for (const req of await sc.keys()) if (!wanted.has(req.url)) await sc.delete(req);
      await self.clients.claim();
    })(),
  );
});

let downloading = null;
async function broadcast(msg) {
  for (const c of await self.clients.matchAll({ includeUncontrolled: true })) c.postMessage(msg);
}
/** Fetch every sprite not yet stored, a few at a time, reporting progress to open pages. */
function downloadAll() {
  if (downloading) return downloading;
  downloading = (async () => {
    const sc = await caches.open(SPRITE_CACHE);
    const all = Object.keys(SPRITES);
    const missing = [];
    for (const p of all) if (!(await sc.match(spriteKey(p), { ignoreVary: true }))) missing.push(p);
    let done = all.length - missing.length;
    await broadcast({ type: 'offline-progress', done, total: all.length });
    let i = 0;
    const worker = async () => {
      while (i < missing.length) {
        const p = missing[i++];
        // a few retries for flaky connections; when truly offline, stop and resume on the next launch
        let ok = false;
        for (let attempt = 0; attempt < 3 && !ok; attempt++) {
          try {
            const res = await fetch(BASE + p, { cache: 'no-cache' });
            if (res.ok) {
              await sc.put(spriteKey(p), res);
              ok = true;
            } else break;
          } catch {
            if (!navigator.onLine) return;
            await new Promise((r) => setTimeout(r, 1000 * (attempt + 1)));
          }
        }
        if (ok) done++;
        if (done % 50 === 0 || done === all.length) await broadcast({ type: 'offline-progress', done, total: all.length });
      }
    };
    await Promise.all(Array.from({ length: 6 }, worker));
    await broadcast({ type: 'offline-progress', done, total: all.length });
    downloading = null;
  })();
  return downloading;
}

self.addEventListener('message', (e) => {
  if (e.data === 'download-all') e.waitUntil(downloadAll());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const rel = url.pathname.startsWith(BASE) ? url.pathname.slice(BASE.length) : null;
  if (rel && SPRITES[rel]) {
    e.respondWith(
      (async () => {
        const sc = await caches.open(SPRITE_CACHE);
        const key = spriteKey(rel);
        const hit = await sc.match(key, { ignoreVary: true });
        if (hit) return hit;
        const res = await fetch(req);
        if (res.ok) sc.put(key, res.clone());
        return res;
      })(),
    );
    return;
  }
  if (req.mode === 'navigate') {
    e.respondWith(
      (async () => {
        const cc = await caches.open(CORE_CACHE);
        try {
          const res = await Promise.race([fetch(req, { cache: 'no-cache' }), new Promise((_, no) => setTimeout(() => no(new Error('timeout')), 3000))]);
          if (res.ok) return res;
        } catch {}
        return (await cc.match('./', { ignoreVary: true })) ?? (await caches.match('./', { ignoreVary: true })) ?? Response.error();
      })(),
    );
    return;
  }
  e.respondWith(
    (async () => {
      const cc = await caches.open(CORE_CACHE);
      // ignoreVary: servers send Vary headers (e.g. Origin for module scripts) that would make lookups miss.
      // Look in the current cache first, then older app versions (a page may still run older code).
      const hit = (await cc.match(req, { ignoreSearch: true, ignoreVary: true })) ?? (await caches.match(req, { ignoreSearch: true, ignoreVary: true }));
      if (hit) return hit;
      return fetch(req);
    })(),
  );
});
